import{_ as i,C as n,o as l,c as h,j as o,a,E as s,a2 as r}from"./chunks/framework.BxGh02fV.js";const b=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{"title":"Dashboard"},"headers":[],"relativePath":"en/guide/dashboard.md","filePath":"en/guide/dashboard.md"}'),d={name:"en/guide/dashboard.md"};function g(u,t,c,p,f,m){const e=n("Capture");return l(),h("div",null,[t[0]||(t[0]=o("h1",{id:"dashboard",tabindex:"-1"},[a("Dashboard "),o("a",{class:"header-anchor",href:"#dashboard","aria-label":'Permalink to "Dashboard"'},"​")],-1)),t[1]||(t[1]=o("p",null,[a("The dashboard is a workspace's "),o("strong",null,"pick-up"),a(" screen. It answers a single question: what is waiting for you? You see in one line what is in progress, then the list of what needs action from you, the state of the backlog and what comes next.")],-1)),s(e,{name:"dashboard",alt:"The dashboard: the In progress line, Waiting for you, Statistics, Up next and Recent activity"}),t[2]||(t[2]=r('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>In progress</strong>: a single line — the active epic, the active story, the task in progress with its identifier, the OPALE phase as a pill and the story&#39;s task counter (for example &quot;2/5 tasks&quot;). A click opens the <a href="/Effortless/en/guide/tasks.html">Tasks</a> screen.</li><li><strong>Waiting for you</strong>: what needs human action, grouped by kind. Each section states its action and count — &quot;To decide: 11 questions&quot;, &quot;To close or resume: 1 task&quot;, &quot;To deliver: 1 commit&quot; —, a sentence says why, and each item shows its age (&quot;52 d&quot;), oldest first; beyond three, <strong>+ N more</strong> unfolds the rest and <strong>Fold</strong> folds it back. The engine lists: <ul><li><strong>open questions</strong>, on a story or on the project;</li><li><strong>unverified acceptance scenarios</strong> of a story whose acceptance tests require a maturity status;</li><li><strong>orphan tasks</strong>: a task still <strong>In progress</strong> while its story or epic is closed, or while its story is not the active one;</li><li>unresolved <strong>critical anomalies</strong> (criticality 1);</li><li><strong>unpushed commits</strong>, <strong>commits since the last delivered version</strong>, and <strong>drift</strong> (code files modified with no task in progress).</li></ul></li><li><strong>Statistics</strong>: a progress bar per backlog level (epics, stories, tasks — &quot;left / total&quot;), and a stacked bar of the evolution registry (live, on hold, closed) with its legend.</li><li><strong>Up next</strong>: the first five evolutions in the order computed by the engine — not the file order.</li><li><strong>Recent activity</strong>: the repository&#39;s latest commits.</li></ul><p>If a source could not be read (a repository with no upstream branch, for instance), the footer of <strong>Waiting for you</strong> says so: &quot;Not checked: …&quot;. Nothing is hidden.</p><p>When there is nothing, each card says so: &quot;Nothing in progress: no active epic.&quot;, &quot;Nothing is waiting for you: …&quot;, &quot;No live evolution.&quot;, &quot;No activity.&quot;</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="act-on-an-item" tabindex="-1">Act on an item <a class="header-anchor" href="#act-on-an-item" aria-label="Permalink to &quot;Act on an item&quot;">​</a></h3><p>Click a line in <strong>Waiting for you</strong>: it opens the screen where you act — <a href="/Effortless/en/guide/knowledge.html">Knowledge</a> for a question or a scenario, <a href="/Effortless/en/guide/backlog.html">Backlog</a> for an orphan task or an anomaly, <a href="/Effortless/en/guide/git.html">Git</a>, <a href="/Effortless/en/guide/release.html">Delivery</a> or <a href="/Effortless/en/guide/drift.html">Drift</a> for the rest.</p><h3 id="open-the-detail" tabindex="-1">Open the detail <a class="header-anchor" href="#open-the-detail" aria-label="Permalink to &quot;Open the detail&quot;">​</a></h3><p><strong>Statistics</strong> and <strong>Up next</strong> open the <a href="/Effortless/en/guide/backlog.html">Backlog</a>; <strong>Recent activity</strong> opens <a href="/Effortless/en/guide/git.html">Git</a>.</p><h3 id="add-tiles" tabindex="-1">Add tiles <a class="header-anchor" href="#add-tiles" aria-label="Permalink to &quot;Add tiles&quot;">​</a></h3><p>A <strong>tile</strong> shows the data you compose. Add as many as you like: <strong>Edit layout</strong>, <strong>Library…</strong>, then <strong>Add</strong> on <strong>Tile</strong>; the new tile lands in the first free spot and the screen scrolls to it. Its <strong>Set up</strong> button opens a panel:</p><ul><li>a <strong>title</strong> (otherwise derived from the first series);</li><li>the <strong>style</strong>: <strong>Number</strong>, <strong>Ring</strong>, <strong>Bars</strong> or <strong>Trend</strong> (one line per series);</li><li>the <strong>period</strong> for flows: 7, 30 or 90 days;</li><li><strong>Split by</strong>: no axis, status, type, criticality or priority;</li><li>the <strong>palette</strong>: Effortless, Monochrome, High contrast, Pastel, or one of your own (see <a href="/Effortless/en/guide/preferences.html">Profile and preferences</a>);</li><li>the <strong>series</strong> — as many as you like. Each picks its dataset (epics, stories, tasks, evolutions), its filters (statuses, types, criticality, priority), its <strong>measure</strong> and its <strong>colour</strong>: <ul><li>counts: total, open, closed, progress;</li><li>flows over the period: created, closed, balance;</li><li>ages and lead times: average age of open items, oldest open item, average lead time;</li><li>for evolutions: average criticality and priority.</li></ul></li><li><strong>Group colours</strong>: when an axis splits the tile, each group can get its own colour.</li></ul><p><strong>Add a series</strong> adds one, <strong>Remove series</strong> takes it away. A colour is taken from the tile&#39;s palette, or picked freely. Every setting applies at once; <strong>OK</strong> closes the panel, <strong>Save layout</strong> keeps the tile&#39;s place. If the filters keep nothing, the tile shows &quot;No data for this type.&quot;</p>',13)),s(e,{name:"tuile-editeur",alt:"The tile settings panel: style, period, axis, palette and series"}),s(e,{name:"dashboard-tuile-composee",alt:"A bar tile: two series of evolutions split by criticality"}),s(e,{name:"dashboard-tuiles",alt:"Four tiles: Tasks as a number, Evolutions as a ring, Anomalies as bars by criticality, Tasks as bars by state"}),t[3]||(t[3]=r('<h3 id="customize-the-layout" tabindex="-1">Customize the layout <a class="header-anchor" href="#customize-the-layout" aria-label="Permalink to &quot;Customize the layout&quot;">​</a></h3><p><strong>Edit layout</strong> switches the dashboard to edit mode: move and resize cards, remove one with its <strong>Remove</strong> button (top right of the card), open the <strong>Library…</strong> (&quot;Widget library&quot;) to <strong>Add</strong> or <strong>Remove</strong> widgets, then <strong>Save layout</strong>. The layout is saved for this project; <strong>Reset</strong> goes back to the default layout.</p><p>The library also keeps the former Phase, Current epic, Story &amp; task, Tasks and Work mode cards. Two of them act:</p><ul><li><strong>Phase</strong>: <strong>Details / Advance</strong> opens the &quot;Lifecycle — phase&quot; drawer, with the <strong>Required documents</strong> of the current phase and the <strong>Advance phase</strong> button when the story is eligible;</li><li><strong>Work mode</strong>: changes the project&#39;s mode, like the <a href="/Effortless/en/guide/settings.html">Project settings</a>.</li></ul><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p><code>effortless_attention</code> returns exactly what this screen shows — the in-progress line, the items waiting, the statistics and the up-next queue — with a readable message. The agent and you see the same list, computed in the same place.</p>',6))])}const k=i(d,[["render",g]]);export{b as __pageData,k as default};
